// 클라우드 컴퓨팅 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const cloud = { cpu: 4, memoryGb: 16, payAsYouGo: true };
console.log(cloud.cpu * cloud.memoryGb);

// IaaS 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const iaas = { vm: "linux", diskGb: 100, userManagesOs: true };
console.log(iaas.userManagesOs);

// PaaS 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const paas = { deploy: "git push", runtime: "node", managesServer: true };
console.log(`${paas.runtime}:${paas.managesServer}`);

// SaaS 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const saas = { app: "mail", installedLocally: false, subscription: true };
console.log(saas.app, saas.subscription);

// 퍼블릭 클라우드 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const cloud = { provider: "aws", tenantIsolation: true, ownedByUser: false };
console.log(cloud.tenantIsolation);

// 프라이빗 클라우드 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const privateCloud = { dedicated: true, selfManaged: true };
console.log(privateCloud.dedicated && privateCloud.selfManaged);

// 하이브리드 클라우드 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const hybrid = { privateDb: true, publicWeb: true };
console.log(hybrid.privateDb && hybrid.publicWeb);

// 멀티 클라우드 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const providers = ["aws", "gcp"];
console.log(providers.length > 1 ? "multi" : "single");

// 리전(Region) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const region = "ap-northeast-2";
console.log(region.startsWith("ap-"));

// 가용 영역(AZ) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const deployment = { azs: ["a", "b"], minAzCount: 2 };
console.log(deployment.azs.length >= deployment.minAzCount);

// 엣지 로케이션 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const edge = { distanceKm: 20, cacheHit: true };
console.log(edge.cacheHit ? "fast" : "origin");

// VPC(가상 사설 클라우드) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const vpc = { cidr: "10.0.0.0/16", subnets: 2 };
console.log(vpc.cidr, vpc.subnets);

// 서브넷 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const subnets = [{ name: "public", cidr: "10.0.1.0/24" }, { name: "private", cidr: "10.0.2.0/24" }];
console.log(subnets.map(s => s.name).join(","));

// 보안 그룹 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const sg = { inbound: [{ port: 443, source: "0.0.0.0/0" }] };
console.log(sg.inbound.some(r => r.port === 443));

// 네트워크 ACL 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const acl = [{ rule: 100, action: "allow", port: 80 }, { rule: 200, action: "deny", port: "*" }];
console.log(acl[0].action);

// 탄력적 IP 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const elasticIp = { address: "203.0.113.10", attachedTo: "web-1" };
console.log(elasticIp.address);

// NAT 게이트웨이 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const nat = { privateCanEgress: true, inboundFromInternet: false };
console.log(nat.privateCanEgress && !nat.inboundFromInternet);

// 인터넷 게이트웨이 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const route = { destination: "0.0.0.0/0", target: "internet-gateway" };
console.log(route.target);

// EC2 인스턴스 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const ec2 = { type: "t3.micro", state: "running" };
console.log(`${ec2.type}:${ec2.state}`);

// 인스턴스 유형 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const types = { "t3.micro": { cpu: 2, mem: 1 }, "m6i.large": { cpu: 2, mem: 8 } };
console.log(types["m6i.large"].mem);

// AMI(머신 이미지) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const ami = { os: "linux", packages: ["node", "nginx"] };
console.log(ami.packages.includes("nginx"));

// 오토 스케일링 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const cpu = 75;
let instances = 2;
if (cpu > 70) instances += 1;
console.log(instances);

// 로드 밸런서(ALB/NLB) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const targets = ["app1", "app2"];
let i = 0;
console.log(targets[i++ % targets.length], targets[i++ % targets.length]);

// S3 스토리지 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const bucket = { name: "assets", objects: ["logo.png"] };
console.log(bucket.objects.includes("logo.png"));

// 객체 스토리지 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const object = { key: "photos/1.jpg", metadata: { type: "image" } };
console.log(object.key, object.metadata.type);

// 블록 스토리지 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const volume = { sizeGb: 100, attached: true };
console.log(volume.attached && volume.sizeGb >= 100);

// 파일 스토리지 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const fileShare = { path: "/mnt/shared", clients: 3 };
console.log(fileShare.clients > 1);

// RDS(관리형 DB) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const rds = { engine: "postgres", automatedBackups: true };
console.log(rds.engine, rds.automatedBackups);

// ElastiCache 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const cache = new Map();
cache.set("user:1", { name: "Ada" });
console.log(cache.get("user:1").name);

// CloudFront 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const request = { path: "/app.js", cacheHit: true };
console.log(request.cacheHit ? "edge" : "origin");

// Route 53 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const record = { name: "api.example.com", type: "A", target: "1.2.3.4" };
console.log(`${record.name}->${record.target}`);

// IAM(계정 권한 관리) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const permission = { action: "s3:GetObject", resource: "bucket/*" };
console.log(permission.action.includes(":"));

// IAM 역할 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const role = { name: "app-role", temporaryCredentials: true };
console.log(role.temporaryCredentials);

// IAM 정책 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const policy = { Effect: "Allow", Action: ["s3:GetObject"], Resource: ["arn:bucket/*"] };
console.log(policy.Effect === "Allow");

// 인프라스트럭처 코드(IaC) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const infra = { resource: "server", count: 2 };
console.log(`${infra.count} ${infra.resource}s`);

// Terraform 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const terraform = { provider: "aws", resources: ["vpc", "ec2"] };
console.log(terraform.resources.length);

// CloudFormation 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const stack = { name: "web-stack", resources: ["ALB", "EC2"] };
console.log(stack.name, stack.resources.includes("ALB"));

// 앤서블(Ansible) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const playbook = ["install nginx", "copy config", "restart service"];
console.log(playbook.join(" -> "));

// 모니터링(CloudWatch) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const metric = { name: "CPUUtilization", value: 82 };
console.log(metric.value > 80 ? "주의" : "정상");

// 알람(Alert) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const errorRate = 0.07;
const alert = errorRate > 0.05;
console.log(alert ? "알람 발송" : "정상");

// 로그 수집 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const logs = ["app started", "user login", "error timeout"];
console.log(logs.filter(v => v.includes("error")));

// 추적(Tracing) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const spans = [{ name: "api", ms: 40 }, { name: "db", ms: 120 }];
console.log(spans.reduce((sum, s) => sum + s.ms, 0));

// 비용 최적화 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const resources = [{ used: true, cost: 10 }, { used: false, cost: 5 }];
console.log(resources.filter(r => r.used).reduce((s, r) => s + r.cost, 0));

// 예약 인스턴스 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const hourly = 1.0;
const reserved = hourly * 0.65;
console.log(reserved);

// 스팟 인스턴스 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const job = { checkpointed: true, interruptionTolerant: true };
console.log(job.checkpointed && job.interruptionTolerant);

// 서버리스(Lambda) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
async function handler(event) { return { statusCode: 200, body: event.name }; }
handler({ name: "Ada" }).then(console.log);

// API Gateway(AWS) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const route = { path: "/users", target: "lambda:getUsers" };
console.log(`${route.path}->${route.target}`);

// SQS 메시지 큐 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const queue = [];
queue.push({ task: "sendEmail" });
console.log(queue.shift().task);

// SNS 알림 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const subscribers = ["email", "sqs", "lambda"];
console.log(subscribers.map(s => `notify:${s}`));

// 이벤트 드리븐 아키텍처 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const event = { type: "OrderPaid", orderId: 7 };
const handlers = { OrderPaid: e => `ship ${e.orderId}` };
console.log(handlers[event.type](event));

// 스토리지 클래스 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const classes = { hot: 0.023, archive: 0.004 };
console.log(classes.archive < classes.hot);

// 데이터 티어링 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const ageDays = 120;
const tier = ageDays > 90 ? "archive" : "hot";
console.log(tier);

// 재해 복구(DR) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const dr = { backup: true, runbook: true, tested: true };
console.log(Object.values(dr).every(Boolean));

// RTO/RPO 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const target = { rtoMinutes: 60, rpoMinutes: 5 };
console.log(target.rtoMinutes > target.rpoMinutes);

// 장애 조치(Failover) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
let active = "primary";
const primaryHealthy = false;
if (!primaryHealthy) active = "standby";
console.log(active);

// 고가용성(HA) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const healthyNodes = 2;
const required = 1;
console.log(healthyNodes >= required);

// SLA 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const availability = 99.9;
console.log(availability >= 99.9 ? "SLA 충족" : "미달");

// 비용 태깅(Cost Tagging) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const resource = { id: "i-1", tags: { team: "api", env: "prod" } };
console.log(resource.tags.team);

// 리소스 그룹 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const group = { name: "payment-prod", resources: ["vm", "db", "lb"] };
console.log(group.resources.length);

// Well-Architected Framework 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const pillars = ["security", "reliability", "cost"];
console.log(pillars.includes("security"));

// 가상화(Virtualization) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const host = { cpu: 16, vms: [{ cpu: 4 }, { cpu: 8 }] };
console.log(host.vms.reduce((s, v) => s + v.cpu, 0));

// 하이퍼바이저(Hypervisor) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const hypervisor = { hostCpu: 32, vmCount: 5 };
console.log(hypervisor.hostCpu / hypervisor.vmCount);

// 베어 메탈 서버 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const server = { dedicatedHardware: true, virtualization: false };
console.log(server.dedicatedHardware && !server.virtualization);

// 엣지 컴퓨팅(Edge Computing) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const latencyMs = { edge: 15, central: 120 };
console.log(latencyMs.edge < latencyMs.central);

// VPN 게이트웨이 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const vpn = { encrypted: true, connects: ["office", "vpc"] };
console.log(vpn.encrypted && vpn.connects.includes("vpc"));

// 전용선(Direct Connect) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const link = { type: "dedicated", bandwidthGbps: 10 };
console.log(link.bandwidthGbps >= 10);

// VPC 피어링(Peering) 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const peering = { vpcA: "10.0.0.0/16", vpcB: "10.1.0.0/16", connected: true };
console.log(peering.connected);

// 트랜짓 게이트웨이 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const tgw = { attachments: ["vpc-a", "vpc-b", "vpn"] };
console.log(tgw.attachments.length);

// DNS 장애 조치 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
let primaryHealthy = false;
const target = primaryHealthy ? "primary.example.com" : "backup.example.com";
console.log(target);

// 로그 아카이빙 예시: Node.js에서 실행 가능한 클라우드 구성 시뮬레이션
const log = { ageDays: 400, storage: "hot" };
if (log.ageDays > 365) log.storage = "archive";
console.log(log.storage);
